insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match) values ('4e3ab029-d797-558f-8017-b4b2566294f0', 'essential-foam', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Essential Foam', 'Poliuretano espanso', 'Poliuretano espanso ad alta densità: sostegno uniforme e stabile, in tre altezze.', 'L''anima monoblocco in poliuretano ad alta densità e alta portanza dà un sostegno uniforme, stabile e duraturo. È il modello più essenziale della gamma, disponibile in H20, H25 e H30. Il rivestimento non è sfoderabile.', 'Anima monoblocco in poliuretano ad alta densità e alta portanza.', '["Anima monoblocco ad alta densità", "Tre altezze: H20, H25, H30", "Sostegno uniforme"]'::jsonb, '["antiacaro", "ipoallergenico", "Free Humidity"]'::jsonb, false, false, false, false, 'Medio-rigido', 'ESS', 'published', 1, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "foam", "welcome": 0, "ventilation": false, "independent_springs": false}'::jsonb) on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('4e3ab029-d797-558f-8017-b4b2566294f0', 'Rigidità indicativa da verificare sul prodotto reale. VERIFY: claim antiacaro / ipoallergenico / Free Humidity da confrontare con etichetta.') on conflict (product_id) do nothing;
insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match) values ('71f76b5b-1cdd-5adb-baa5-614ec6ad9552', 'memory-duo', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Memory Duo', 'Memory Foam 2 strati', 'Memory Foam premium su base in poliuretano ad alta densità. Sfoderabile e reversibile.', 'Uno strato di comfort in Memory Foam premium ad alta densità poggia su una base portante in poliuretano ad alta densità. È più accogliente dell''Essential ed è reversibile: un lato invernale in Memory e un lato più fresco per l''estate. Il rivestimento è sfoderabile.', 'Memory Foam premium ad alta densità + base di supporto in poliuretano ad alta densità.', '["Memory Foam premium", "Lato invernale e lato estivo", "Sfoderabile"]'::jsonb, '["antiacaro", "ipoallergenico", "Free Humidity"]'::jsonb, true, true, true, false, 'Medio-rigido e accogliente', 'MD', 'published', 2, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "memory", "welcome": 2, "ventilation": false, "independent_springs": false}'::jsonb) on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('71f76b5b-1cdd-5adb-baa5-614ec6ad9552', 'Rigidità indicativa da verificare sul prodotto reale. Memory ~5 cm come riferimento visual/copy; non pubblicare lo spessore dei singoli strati finché non verificato. VERIFY: claim antiacaro / ipoallergenico / Free Humidity da confrontare con etichetta. CONFLICT prezzo H25 160x190: listino recente €220 vs indicazione precedente €250. Usato €220, da confermare.') on conflict (product_id) do nothing;
