insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match) values ('0eedacdc-4815-5c09-b7d4-2cce6820b44d', 'pocket-2400-elite', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Pocket 2400 Elite', '2400 molle insacchettate + Memory', 'Molle indipendenti insacchettate e Memory Foam: il nostro Hybrid più sostenuto.', 'Molle indipendenti insacchettate, uno strato di comfort in Memory Foam ed elementi in poliuretano ad alta densità per stabilizzazione e supporto. Le 2400 molle sono riferite alla misura 160×190; sulle altre misure il molleggio è proporzionato alla superficie. Pensato per chi cerca più sostegno e per chi dorme in due. Rivestimento sfoderabile.', 'Molle indipendenti insacchettate + Memory Foam + elementi in poliuretano ad alta densità per stabilizzazione e supporto.', '["Molle indipendenti insacchettate", "Strato di comfort in Memory", "Sfoderabile"]'::jsonb, '["antiacaro", "ipoallergenico", "Free Humidity"]'::jsonb, true, false, false, true, 'Sostenuto / medio-rigido', 'P2400', 'published', 4, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "molle", "welcome": 1, "ventilation": false, "independent_springs": true}'::jsonb) on conflict (id) do nothing;
